/**
 * Known vanilla `server.properties` keys.
 *
 * Source of truth: files generated by the official server jars of 1.14 → 26.3 in throwaway
 * containers (2026-10-12) and string constants of `DedicatedServerProperties` in the 26.3 jar.
 *  - `since` is the first checked version that writes the key (null = present in every checked
 *    version, i.e. ≤ 1.14). Patch releases between checked versions were not all inspected, so a
 *    key may exist slightly earlier than stated.
 *  - `removedIn` is the first version that no longer reads it. 1.21.9 moved `pvp`,
 *    `allow-nether`, `enable-command-block` and `spawn-monsters` to game rules (verified: absent
 *    from 26.3 DedicatedServerProperties, game rules present in the 1.21.9+ jars, absent in 1.21.8).
 *  - Defaults are those written by 26.3 unless noted (e.g. `white-list` defaults to true only
 *    since 26.3).
 */

export type PropertyType = "boolean" | "integer" | "string" | "enum";

export interface PropertySpec {
  key: string;
  type: PropertyType;
  default: string;
  description: string;
  min?: number;
  max?: number;
  values?: readonly string[];
  since: string | null;
  removedIn?: string;
  /** Where the setting lives after removal (game rule id per version range). */
  replacedBy?: string;
  /** Contains a credential: redact for display, never log. */
  secret?: boolean;
  /** Set by BlockForge (ports, RCON, management API); user edits are overridden. */
  platformManaged?: boolean;
  /** Free-form notes for UI help. */
  notes?: string;
}

