export const PROPERTY_SCHEMA: ReadonlyMap<string, PropertySpec> = new Map(SPECS.map((s) => [s.key, s]));

export const SECRET_PROPERTY_KEYS: readonly string[] = SPECS.filter((s) => s.secret).map((s) => s.key);
export const PLATFORM_MANAGED_PROPERTY_KEYS: readonly string[] = SPECS.filter((s) => s.platformManaged).map((s) => s.key);

export function propertySpec(key: string): PropertySpec | undefined {
  return PROPERTY_SCHEMA.get(key);
}

